--
-- Name: SystemSetting; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public."SystemSetting" (
    id text NOT NULL,
    key text NOT NULL,
    value text NOT NULL,
    type text NOT NULL,
    description text,
    category text NOT NULL,
    "isPublic" boolean DEFAULT false NOT NULL,
    "isEditable" boolean DEFAULT true NOT NULL,
